# This file is regenerated by the release workflow in Jleagle/coffee on every
# tagged release — do not edit the url/sha256 by hand.
#
# Install (upgrading from the old formula: `brew services stop coffee &&
# brew uninstall coffee` first):
#   brew install --cask Jleagle/coffee/coffee
cask "coffee" do
  version "0.0.1"
  sha256 "c736be365e12eb51cb19e21975ed30e31b5b691cf48fbebb7dc6179b95bfec77"

  url "https://github.com/Jleagle/coffee/releases/download/v0.0.1/coffee-v0.0.1-macos-universal.tar.gz"
  name "Coffee"
  desc "Coffee shop CLI and macOS menu bar app"
  homepage "https://github.com/Jleagle/coffee"

  depends_on macos: ">= :ventura"

  app "Coffee.app"
  binary "coffee"

  # The app is ad-hoc signed, not notarized, so Gatekeeper would block
  # the quarantined download on first launch — strip the attribute
  # from the installed app and the staged CLI binary instead.
  postflight do
    system_command "/usr/bin/xattr",
                   args: ["-dr", "com.apple.quarantine", "#{appdir}/Coffee.app"],
                   must_succeed: false
    system_command "/usr/bin/xattr",
                   args: ["-dr", "com.apple.quarantine", staged_path.to_s],
                   must_succeed: false
  end
end
